1	// ── SQLite Database Module for Polyglot ──────────────────────────────────────
2	// Replaces JSON file storage with a local SQLite database.
3	// Uses better-sqlite3 (synchronous, fast, no async overhead).
4	// Database file: data/polyglot.db (created automatically on first access).
5	
6	const Database = require('better-sqlite3');
7	const path = require('path');
8	const fs = require('fs');
9	
10	const DB_DIR = path.join(__dirname, '..', 'data');
11	const DB_PATH = path.join(DB_DIR, 'polyglot.db');
12	const HOME = process.env.HOME || process.env.USERPROFILE || '';
13	const ORG_DIR = path.join(HOME, '.claude', 'org');
14	
15	let _db = null;
16	
17	// ── Database Lifecycle ──────────────────────────────────────────────────────
18	
19	function getDb() {
20	  if (_db) return _db;
21	  fs.mkdirSync(DB_DIR, { recursive: true });
22	  _db = new Database(DB_PATH);
23	  _db.pragma('journal_mode = WAL');
24	  _db.pragma('foreign_keys = ON');
25	  _db.pragma('busy_timeout = 5000');
26	  _db.pragma('synchronous = NORMAL');
27	
28	  // Integrity check — catch corruption early
29	  try {
30	    const check = _db.pragma('integrity_check');
31	    if (check[0]?.integrity_check !== 'ok') {
32	      console.error('[db] INTEGRITY CHECK FAILED:', check);
33	    }
34	  } catch (err) {
35	    console.error('[db] Integrity check error:', err.message);
36	  }
37	
38	  runMigrations(_db);
39	  return _db;
40	}
41	
42	function close() {
43	  if (_db) { _db.close(); _db = null; }
44	}
45	
46	// ── Prepared Statement Cache ────────────────────────────────────────────────
47	
48	const _stmts = {};
49	function stmt(sql) {
50	  if (!_stmts[sql]) _stmts[sql] = getDb().prepare(sql);
51	  return _stmts[sql];
52	}
53	
54	// ── Schema Migrations ───────────────────────────────────────────────────────
55	
56	function runMigrations(db) {
57	  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
58	    version INTEGER PRIMARY KEY,
59	    name TEXT NOT NULL,
60	    applied_at TEXT NOT NULL DEFAULT (datetime('now'))
61	  )`);
62	
63	  const applied = new Set(db.prepare('SELECT version FROM schema_migrations').all().map(r => r.version));
64	
65	  const migrations = [
66	    { version: 1, name: 'create_all_tables', fn: createAllTables },
67	    { version: 2, name: 'import_json_data', fn: importJsonData },
68	    { version: 3, name: 'create_change_log', fn: createChangeLog },
69	  ];
70	
71	  for (const mig of migrations) {
72	    if (applied.has(mig.version)) continue;
73	    console.log(`[db] Running migration ${mig.version}: ${mig.name}`);
74	    db.transaction(() => {
75	      mig.fn(db);
76	      db.prepare('INSERT INTO schema_migrations (version, name) VALUES (?, ?)').run(mig.version, mig.name);
77	    })();
78	  }
79	}
